#!/bin/bash
set -eo pipefail
test "$(id -un)" = sunyiq
timeout --signal=KILL 20 /data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -I -B - <<'FIXED_SOURCE_NAMES_PYTHON'
import base64, datetime, gzip, hashlib, json, signal
source = base64.b64decode('', validate=True)
if hashlib.sha256(source).hexdigest() != 'a0498471bde210e6f34711310859e21172fab1d009863e084a1d0df6733e2871':
    raise ValueError('Reviewed metadata reader source bytes differ')
namespace = {'__name__': 'fixed_metadata_scope'}
exec(compile(source, '<fixed_directory_metadata_v1>', 'exec'), namespace)
def expired(_signal, _frame):
    raise TimeoutError('Ten-second fixed directory bound')
signal.signal(signal.SIGALRM, expired)
signal.alarm(10)
report = namespace['inspect']()
signal.alarm(0)
report.update(reader_sha256='a0498471bde210e6f34711310859e21172fab1d009863e084a1d0df6733e2871', server_timestamp=datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=8))).isoformat())
raw = json.dumps(report, ensure_ascii=True, separators=(',', ':'), allow_nan=False).encode()
if len(raw) > 262144:
    raise ValueError('Metadata report byte bound')
print('SOURCE_NAMES_REPORT_SHA256='+hashlib.sha256(raw).hexdigest())
print('SOURCE_NAMES_GZIP_BASE64_BEGIN')
print(base64.b64encode(gzip.compress(raw, mtime=0)).decode())
print('SOURCE_NAMES_GZIP_BASE64_END')
FIXED_SOURCE_NAMES_PYTHON
printf 'SOURCE_NAMES_QUERY_COMPLETE
'
